const config=$('Demo Configuration').first().json;
const first=$input.first()?.json;
const rows=Array.isArray(first)?first:(Array.isArray(first?.observations)?first.observations:$input.all().map(i=>i.json));
const accepted=[]; const rejected=[]; const seen=new Set();
for(const [i,row] of rows.entries()){
  try{
    const route=String(row.route??"").trim().toUpperCase();
    const carrier=String(row.carrier_code??row.carrier??"").trim().toUpperCase();
    const fare=Number(row.total_fare??row.totalFare);
    const observed=new Date(row.observed_at??config.started_at);
    const travel=new Date(row.travel_date);
    const currency=String(row.currency??"INR").toUpperCase();
    const advance=Math.round((travel-observed)/86400000);
    if(!/^[A-Z]{3}-[A-Z]{3}$/.test(route)) throw new Error("invalid route");
    if(!/^[A-Z0-9]{2,3}$/.test(carrier)) throw new Error("invalid carrier_code");
    if(!(fare>0)||fare>1000000) throw new Error("invalid total_fare");
    if(currency!=="INR") throw new Error("currency must be INR");
    if(Number.isNaN(observed.getTime())||Number.isNaN(travel.getTime())) throw new Error("invalid date");
    if(advance<1||advance>365) throw new Error("advance_days outside 1..365");
    const key=route+"|"+carrier+"|"+travel.toISOString().slice(0,10)+"|"+Math.round(fare*100);
    if(seen.has(key)) throw new Error("duplicate observation");
    seen.add(key);
    const window=[1,7,15,30,45].find(w=>advance<=w)??45;
    const age=Math.max(0,(new Date(config.started_at)-observed)/60000);
    const freshness=Math.max(0,Math.min(1,1-age/config.freshness_limit_minutes));
    accepted.push({route,carrier_code:carrier,observed_at:observed.toISOString(),travel_date:travel.toISOString().slice(0,10),total_fare:Math.round(fare*100)/100,advance_days:advance,lead_time_window:"T+"+window,currency,source:row.source??"airindex-demo-replay",freshness_score:Number(freshness.toFixed(4)),row_number:i+1});
  }catch(e){rejected.push({row_number:i+1,reason:e.message??String(e)});}
}
if(!accepted.length) throw new Error("No valid observations");
return [{json:{...config,observations:accepted,source_count:rows.length,rejected_count:rejected.length,rejected_examples:rejected.slice(0,10)}}];

const d=$input.first().json; const byRoute={};
for(const o of d.observations)(byRoute[o.route]??=[]).push(o.total_fare);
const med={}; for(const [r,fs] of Object.entries(byRoute)){const v=[...fs].sort((a,b)=>a-b);const m=Math.floor(v.length/2);med[r]=v.length%2?v[m]:(v[m-1]+v[m])/2;}
const observations=d.observations.map(o=>{const dev=((o.total_fare-med[o.route])/med[o.route])*100;const anomaly=Math.abs(dev)>=d.anomaly_threshold_pct;const q=Math.max(0,Math.min(1,0.55+0.30*o.freshness_score+0.15*(anomaly?0.25:1)));return {...o,route_median_fare:Number(med[o.route].toFixed(2)),deviation_pct:Number(dev.toFixed(2)),anomaly_flag:anomaly,quality_score:Number(q.toFixed(4))};});
const anomalies=observations.filter(o=>o.anomaly_flag).length;
return [{json:{...d,observations,anomaly_count:anomalies,anomaly_rate_pct:Number((100*anomalies/observations.length).toFixed(2)),distinct_routes:Object.keys(med).length,quality_avg:Number((observations.reduce((s,o)=>s+o.quality_score,0)/observations.length).toFixed(4))}}];

const d=$input.first().json; const groups={};
for(const o of d.observations){const k=o.route+"|"+o.lead_time_window;(groups[k]??=[]).push(o);}
return Object.entries(groups).map(([group,observations])=>({json:{...d,batch_group:group,observations}}));

const batchSize=$('Demo Configuration').first().json.batch_size; const out=[]; let n=0;
for(const item of $input.all()){for(let i=0;i<item.json.observations.length;i+=batchSize){n++;out.push({json:{run_id:item.json.run_id,batch_id:item.json.run_id+"-b"+n,batch_group:item.json.batch_group,batch_number:n,observations:item.json.observations.slice(i,i+batchSize)}});}}
return out;
